// 25 · The coach takes the player off when he is spent, or late on when a poor match meets low trust.
function exitReason(t){if(match.training||t.onPitch===false||t.minute<60)return null;if(match.energy<30)return 'À bout de forces';if(t.minute>=72&&!match.entered&&match.goals+match.assists===0&&match.losses>=2&&career.trust<45)return 'Le coach n’est pas convaincu';return null;}
