function say(event,extra={}){if(!match||match.training)return;if(['goal_us','hero_goal','assist'].includes(event))ambience.goal();else if(event==='goal_them')ambience.groan();else if(['save','miss','frame'].includes(event))ambience.ooh();const line=commentLine(event,{minute:Math.floor(match.minute),us:match.us,them:match.them,name:career.name,goals:match.goals,careerGoals:career.goals,scenario:match.scenario,...extra});if(!line)return;$('commentary').textContent=line;$('commentary').hidden=false;match.commentAt=time;match.lastComment=line;}
