 if(a.phase==='interval'&&t){const y=t.ball.y;danger=t.owner.team===0?clamp((y-.6)/.4,0,1):clamp((.4-y)/.4,0,1)*.8;}else if(!a.ended){chance=true;danger=clamp((30-Math.hypot(a.ball.x,a.ball.z+20))/20,0,1);}
